/****************************************************************************
 * Name: file_fsync
 *
 * Description:
 *   Equivalent to the standard fsync() function except that is accepts a
 *   struct file instance instead of a file descriptor and it does not set
 *   the errno variable.
 *
 ****************************************************************************/

int file_fsync(FAR struct file *filep)
{
  FAR struct inode *inode;
  int ret;

  /* Is this inode a registered mountpoint? Does it support the
   * sync operations may be relevant to device drivers but only
   * the mountpoint operations vtable contains a sync method.
   */

  inode = filep->f_inode;
  if (inode != NULL)
    {
#ifndef CONFIG_DISABLE_MOUNTPOINT
      if (INODE_IS_MOUNTPT(inode))
        {
          if (inode->u.i_mops && inode->u.i_mops->sync)
            {
              /* Yes, then tell the mountpoint to sync this file */

              return inode->u.i_mops->sync(filep);
            }
        }
      else
#endif
      if (inode->u.i_ops && inode->u.i_ops->ioctl)
        {
          ret = inode->u.i_ops->ioctl(filep, BIOC_FLUSH, 0);
          return ret >= 0 ? 0 : ret;
        }
    }

  return -EINVAL;
}

/****************************************************************************
 * Name: fsync
 *
 * Description:
 *   This func simply binds inode sync methods to the sync system call.
 *
 ****************************************************************************/

int fsync(int fd)
{
  FAR struct file *filep;
  int ret;

  /* fsync() is a cancellation point */

  enter_cancellation_point();

  /* Get the file structure corresponding to the file descriptor. */

  ret = file_get(fd, &filep);
  if (ret < 0)
    {
      goto errout;
    }

  /* Perform the fsync operation */

  ret = file_fsync(filep);
  file_put(filep);
  if (ret < 0)
    {
      goto errout;
    }

  leave_cancellation_point();
  return ret;

errout:
  leave_cancellation_point();
  set_errno(-ret);
  return ERROR;
 *
 ****************************************************************************/

int file_close(FAR struct file *filep)
{
  struct inode *inode;
  int ret = OK;

  DEBUGASSERT(filep != NULL);
  inode = filep->f_inode;

  /* Check if the struct file is open (i.e., assigned an inode) */

  if (inode)
    {
#ifdef CONFIG_FS_NOTIFY
      /* We lose the path and inode during close and release, so obtain it
       * in advance. Then we pass it to notify_close or pathcache_close.
       */

      FAR char *path = file_get_path(filep);
#elif defined(CONFIG_FS_PATHCACHE)
      FAR char *path = INODE_IS_PATHCACHE(inode) ? file_get_path(filep) :
                                                   NULL;
#endif

      file_closelk(filep);

      /* Close the file, driver, or mountpoint. */

      if (inode->u.i_ops && inode->u.i_ops->close)
        {
#ifdef CONFIG_FS_PATHCACHE
          if (INODE_IS_PATHCACHE(inode))
            {
              /* The inode is using pathcache */

              pathcache_close(filep, path);
            }
#endif

          /* Perform the close operation */

          ret = inode->u.i_ops->close(filep);
        }

      /* And release the inode */

      if (ret >= 0)
        {
#ifdef CONFIG_FS_NOTIFY
          if (path != NULL)
            {
              notify_close(path, filep->f_oflags);
            }
#endif

          inode_release(inode);
        }

