   100	/* Build OpenAI-format assistant message with tool_calls at the top level */
   101	static void add_assistant_message(cJSON* messages, const llm_response_t* resp)
   102	{
   103	    cJSON* asst_msg = cJSON_CreateObject();
   104	    cJSON_AddStringToObject(asst_msg, "role", "assistant");
   105	
   106	    if (resp->text && resp->text_len > 0) {
   107	        cJSON_AddStringToObject(asst_msg, "content", resp->text);
   108	    } else {
   109	        cJSON_AddNullToObject(asst_msg, "content");
   110	    }
   111	
   112	    /* Kimi thinking mode: echo back reasoning_content or the API returns 400 */
   113	    if (resp->reasoning_content && resp->reasoning_content[0]) {
   114	        cJSON_AddStringToObject(asst_msg, "reasoning_content",
   115	            resp->reasoning_content);
   116	    }
   117	
   118	    if (resp->call_count > 0) {
   119	        cJSON* tool_calls = cJSON_CreateArray();
   120	        for (int i = 0; i < resp->call_count; i++) {
   121	            const llm_tool_call_t* call = &resp->calls[i];
   122	            cJSON* tc = cJSON_CreateObject();
   123	            cJSON_AddStringToObject(tc, "id", call->id);
   124	            cJSON_AddStringToObject(tc, "type", "function");
   125	
   126	            cJSON* func_obj = cJSON_CreateObject();
   127	            cJSON_AddStringToObject(func_obj, "name", call->name);
   128	            cJSON_AddStringToObject(func_obj, "arguments",
   129	                call->input ? call->input : "{}");
   130	            cJSON_AddItemToObject(tc, "function", func_obj);
   131	            cJSON_AddItemToArray(tool_calls, tc);
   132	        }
   133	        cJSON_AddItemToObject(asst_msg, "tool_calls", tool_calls);
   134	    }
   135	
   136	    cJSON_AddItemToArray(messages, asst_msg);
   137	}
