   165	/* Parallel tool execution context */
   166	typedef struct {
   167	    const llm_tool_call_t* call;
   168	    char* output;
   169	    size_t output_size;
   170	    bool from_pool;
   171	    char channel[16];
   172	    char chat_id[64];
   173	} tool_task_t;
   174	
   175	static void* tool_exec_thread(void* arg)
   176	{
   177	    tool_task_t* t = (tool_task_t*)arg;
   178	
   179	    t->output[0] = '\0';
   180	    char* patched = inject_cron_context(
   181	        t->call->name, t->call->input, t->channel, t->chat_id);
   182	    agent_tool_exec_streamed(t->call->name,
   183	        patched ? patched : t->call->input,
   184	        t->output, t->output_size);
   185	    free(patched);
   186	    syslog(LOG_INFO, "[%s] Tool %s result: %d bytes\n",
   187	        TAG, t->call->name, (int)strlen(t->output));
   188	    return NULL;
   189	}
